{
  "name": "Keysight E4980A 精密LCR表",
  "name_en": "Keysight E4980A Precision LCR Meter",
  "manufacturer": "Keysight Technologies",
  "description": "这是一台台式精密LCR表，可在设定交流测试条件和直流偏压下测量电容、电感、电阻及阻抗相关参数。它常用于电子元件、半导体器件和材料样品的C-V表征与阻抗分析。",
  "description_en": "This is a benchtop precision LCR meter used to measure capacitance, inductance, resistance, and related impedance parameters under defined AC test conditions and DC bias. It is commonly used for C-V characterization and impedance analysis of electronic components, semiconductor devices, and material samples.",
  "tag_hints": [
    "LCR meter",
    "C-V measurement",
    "impedance measurement",
    "capacitance measurement",
    "DC bias sweep",
    "electronic component characterization"
  ],
  "actions": [
    {
      "action_name": "auto-close_instrument",
      "description": "安全关闭仪器。",
      "description_en": "Safely shut down the instrument."
    },
    {
      "action_name": "auto-initialize_instrument",
      "description": "初始化并配置仪器测量参数。",
      "description_en": "Initialize and configure the instrument measurement parameters."
    },
    {
      "action_name": "auto-perform_measurement",
      "description": "设置偏压并执行一次C-V测量。",
      "description_en": "Set the bias voltage and perform a single C-V measurement."
    },
    {
      "action_name": "auto-setup_styles",
      "description": "设置测量界面的显示样式。",
      "description_en": "Set up the display style of the measurement interface."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建测量界面控件。",
      "description_en": "Create the measurement interface widgets."
    },
    {
      "action_name": "auto-create_info_frame",
      "description": "创建设备与测量信息区域。",
      "description_en": "Create the device and measurement information panel."
    },
    {
      "action_name": "auto-create_input_frame",
      "description": "创建测量参数输入区域。",
      "description_en": "Create the measurement parameter input panel."
    },
    {
      "action_name": "auto-create_console_frame",
      "description": "创建测量日志与控制台区域。",
      "description_en": "Create the measurement log and console panel."
    },
    {
      "action_name": "auto-create_graph_frame",
      "description": "创建测量曲线显示区域。",
      "description_en": "Create the measurement graph display panel."
    },
    {
      "action_name": "auto-log",
      "description": "记录测量过程日志。",
      "description_en": "Record measurement process logs."
    },
    {
      "action_name": "auto-start_sweep",
      "description": "开始偏压扫描测量。",
      "description_en": "Start a bias sweep measurement."
    },
    {
      "action_name": "auto-stop_sweep",
      "description": "停止偏压扫描测量。",
      "description_en": "Stop a bias sweep measurement."
    }
  ]
}

